import numpy as np,pandas as pd
def metrics(d):
 c=d.Close.dropna();last=float(c.iloc[-1]);ma50=float(c.tail(50).mean());ma200=float(c.tail(200).mean());r3=last/c.iloc[-64]-1;r12=last/c.iloc[-253]-1;vol=float(c.pct_change().tail(60).std()*np.sqrt(252));dd=float((c.tail(252)/c.tail(252).cummax()-1).min());prev=d.Close.shift();tr=pd.concat([(d.High-d.Low).abs(),(d.High-prev).abs(),(d.Low-prev).abs()],axis=1).max(axis=1);atr=float(tr.ewm(alpha=1/14,adjust=False).mean().iloc[-1]);tech=max(0,min(100,50+(15 if last>ma200 else -20)+(10 if ma50>ma200 else -10)+(8 if last>ma50 else -8)));mom=max(0,min(100,50+r3*90+r12*25));risk=max(0,min(100,100-vol*100+dd*30));return {'price':last,'ma50':ma50,'ma200':ma200,'atr14':atr,'technical_score':tech,'momentum_score':mom,'risk_score':risk,'return_3m':r3,'return_12m':r12,'volatility':vol}
